<?php
/** Internal shared feedback entry for the starter page and authenticated toolkit. */
function neurosaas_feedback_widget(string $url): void {
    $safe=htmlspecialchars($url,ENT_QUOTES,'UTF-8');
    echo '<a data-feedback-open href="'.$safe.'" style="position:fixed;right:18px;top:14px;z-index:9999;background:#171717;color:white;padding:8px 12px;border-radius:8px;text-decoration:none;font:14px system-ui">Идеи для доработки</a><dialog id="neuro-feedback" style="position:fixed;inset:auto;left:4vw;top:8vh;width:min(800px,92vw);height:80vh;margin:0;padding:0;border:1px solid #999;border-radius:12px"><div data-feedback-drag tabindex="0" aria-label="Переместить окно стрелками" style="display:flex;justify-content:space-between;gap:12px;cursor:move;touch-action:none;background:#eee;padding:12px"><strong>Идеи · перетащите за эту полосу</strong><button type="button" data-feedback-close aria-label="Закрыть">×</button></div><iframe title="Идеи для доработки" style="border:0;width:100%;height:calc(100% - 60px)"></iframe></dialog>';
    echo <<<'HTML'
<script>(()=>{const a=document.querySelector('[data-feedback-open]'),d=document.getElementById('neuro-feedback'),h=d.querySelector('[data-feedback-drag]');let at=null;const move=(x,y)=>{d.style.left=Math.max(0,Math.min(innerWidth-d.offsetWidth,x))+'px';d.style.top=Math.max(0,Math.min(innerHeight-d.offsetHeight,y))+'px'};a.addEventListener('click',e=>{if(!d.showModal)return;e.preventDefault();const f=d.querySelector('iframe');if(!f.src){const u=new URL(a.href);u.searchParams.set('embedded','1');f.src=u.href}d.showModal()});d.querySelector('[data-feedback-close]').addEventListener('click',()=>d.close());h.addEventListener('pointerdown',e=>{if(e.target.closest('button'))return;const r=d.getBoundingClientRect();at={x:e.clientX,y:e.clientY,left:r.left,top:r.top};h.setPointerCapture(e.pointerId)});h.addEventListener('pointermove',e=>{if(at)move(at.left+e.clientX-at.x,at.top+e.clientY-at.y)});['pointerup','pointercancel'].forEach(t=>h.addEventListener(t,()=>at=null));h.addEventListener('keydown',e=>{const v={ArrowLeft:[-10,0],ArrowRight:[10,0],ArrowUp:[0,-10],ArrowDown:[0,10]}[e.key];if(v){e.preventDefault();const r=d.getBoundingClientRect();move(r.left+v[0],r.top+v[1])}})})();</script>
HTML;
}
